mapper.select:
SELECT A.CMPNY_CD AS cmpnyCd , A.ROLE_CD AS roleCd , A.ROLE_NM AS roleNm , A.ROLE_TY AS roleTy , A.ROLE_PTTRN AS rolePttrn , A.ROLE_DC AS roleDc , A.ROLE_SORT AS roleSort , DATE_FORMAT(A.CREATION_DT, '%Y-%m-%d') AS creationDt FROM CM_ROLE A WHERE A.CMPNY_CD = #{cmpnyCd}
AND A.ROLE_TY = #{roleTy}
AND (A.ROLE_CD LIKE CONCAT('%', #{searchKeyword}, '%') OR A.ROLE_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR IFNULL(A.ROLE_DC,'') LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY A.ROLE_SORT, A.ROLE_CD LIMIT #{recordCountPerPage} OFFSET #{offset}

SELECT COUNT(*) FROM CM_ROLE A WHERE A.CMPNY_CD = #{cmpnyCd}
AND A.ROLE_TY = #{roleTy}
AND (A.ROLE_CD LIKE CONCAT('%', #{searchKeyword}, '%') OR A.ROLE_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR IFNULL(A.ROLE_DC,'') LIKE CONCAT('%', #{searchKeyword}, '%'))

