mapper.update:
UPDATE CM_ROLE
   SET ROLE_NM = #{roleNm}
     , ROLE_TY = #{roleTy}
     , ROLE_PTTRN = #{rolePttrn}
     , ROLE_DC = #{roleDc}
     , ROLE_SORT = #{roleSort, jdbcType=SMALLINT}
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND ROLE_CD = #{roleCd}

mapper.delete:
DELETE FROM CM_ROLE
 WHERE CMPNY_CD = #{cmpnyCd}
   AND ROLE_CD = #{roleCd}

DELETE FROM CM_AUTHOR_ROLE_RELATE
 WHERE CMPNY_CD = #{cmpnyCd}
   AND ROLE_CD = #{roleCd}

DELETE FROM CM_AUTHOR_ROLE_RELATE
 WHERE CMPNY_CD = #{cmpnyCd}
   AND AUTHOR_CD = #{authorCd}

mapper.select:
SELECT R.CMPNY_CD AS cmpnyCd , R.ROLE_CD AS roleCd , R.ROLE_NM AS roleNm , R.ROLE_TY AS roleTy , R.ROLE_PTTRN AS rolePttrn , R.ROLE_DC AS roleDc , R.ROLE_SORT AS roleSort , CASE WHEN AR.ROLE_CD IS NOT NULL THEN 'Y' ELSE 'N' END AS mappedYn FROM CM_ROLE R LEFT JOIN CM_AUTHOR_ROLE_RELATE AR ON AR.CMPNY_CD = R.CMPNY_CD AND AR.ROLE_CD = R.ROLE_CD AND AR.AUTHOR_CD = #{authorCd} WHERE R.CMPNY_CD = #{cmpnyCd}
AND R.ROLE_TY = #{roleTy}
AND (R.ROLE_CD LIKE CONCAT('%', #{searchKeyword}, '%') OR R.ROLE_NM LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY R.ROLE_SORT, R.ROLE_CD
